export type DarwinAclInspection = {
    kind: "none";
} | {
    kind: "present";
    inheritsToFiles: boolean;
    inheritsToDirectories: boolean;
} | {
    kind: "unknown";
    reason: string;
};
/** Inspect one no-follow descriptor. Unknown is never evidence of no ACL. */
export declare function inspectDarwinAcl(path: string): DarwinAclInspection;
